CREATE TABLE IF NOT EXISTS srikandi(id INTEGER PRIMARY KEY AUTOINCREMENT,unit_id TEXT NOT NULL REFERENCES units(id),full_name TEXT NOT NULL,category TEXT NOT NULL,joined_year INTEGER NOT NULL,whatsapp TEXT NOT NULL,photo_key TEXT NOT NULL,consent_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','inactive')),member_no TEXT UNIQUE,card_token TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX IF NOT EXISTS srikandi_unit ON srikandi(unit_id,status); CREATE TABLE IF NOT EXISTS athlete_contacts(member_id INTEGER PRIMARY KEY REFERENCES members(id),phone TEXT NOT NULL,relationship TEXT NOT NULL,consent_at TEXT NOT NULL);